begin;
insert into public.hr_permissions(code,name,module) values ('settings.recurring_expenses.view','View recurring expenses','Settings'),('settings.recurring_expenses.manage','Manage recurring expenses','Settings') on conflict(code) do update set name=excluded.name,module=excluded.module;
insert into public.hr_role_permissions(role_id,permission_id) select r.id,p.id from public.hr_roles r cross join public.hr_permissions p where lower(r.name)='admin' and p.code in('settings.recurring_expenses.view','settings.recurring_expenses.manage') on conflict do nothing;
create table if not exists public.clinic_recurring_expenses(id bigint generated by default as identity primary key,clinic_id bigint not null references public.clinics(id) on delete cascade,branch_id bigint not null references public.branches(id) on delete cascade,name text not null,amount numeric(14,2) not null check(amount>0),category text not null default 'other',account_key text not null default 'other_expense',due_day smallint not null default 1 check(due_day between 1 and 28),supplier_name text,assigned_to_staff_id bigint references public.staff(id) on delete set null,details text,is_active boolean not null default true,last_generated_month date,created_by_staff_id bigint references public.staff(id) on delete set null,updated_by_staff_id bigint references public.staff(id) on delete set null,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(clinic_id,branch_id,name));
alter table public.clinic_recurring_expenses enable row level security;
create policy recurring_expenses_read on public.clinic_recurring_expenses for select to authenticated using(clinic_id=public.current_clinic_id() and public.has_any_hr_permission(array['settings.recurring_expenses.view','settings.recurring_expenses.manage','settings.manage','accounting.manage']));
create policy recurring_expenses_write on public.clinic_recurring_expenses for all to authenticated using(clinic_id=public.current_clinic_id() and public.has_any_hr_permission(array['settings.recurring_expenses.manage','settings.manage','accounting.manage'])) with check(clinic_id=public.current_clinic_id() and public.has_any_hr_permission(array['settings.recurring_expenses.manage','settings.manage','accounting.manage']));
create or replace function public.generate_recurring_expenses(p_branch_id bigint,p_month date default current_date) returns integer language plpgsql security definer set search_path=public as $$declare r record;generated integer:=0;month_start date:=date_trunc('month',p_month)::date;expense_date date;begin if not public.has_any_hr_permission(array['settings.recurring_expenses.manage','settings.manage','accounting.manage']) then raise exception 'Permission denied';end if;for r in select * from public.clinic_recurring_expenses where clinic_id=public.current_clinic_id() and branch_id=p_branch_id and is_active and(last_generated_month is null or last_generated_month<month_start) loop expense_date:=month_start+(r.due_day-1);insert into public.clinic_expenses(clinic_id,branch_id,expense_number,expense_date,name,details,category,account_key,supplier_name,assigned_to_staff_id,quantity,total_amount) values(r.clinic_id,r.branch_id,'REC-'||r.id||'-'||to_char(month_start,'YYYYMM'),expense_date,r.name,r.details,r.category,r.account_key,r.supplier_name,r.assigned_to_staff_id,1,r.amount) on conflict(clinic_id,expense_number) do nothing;update public.clinic_recurring_expenses set last_generated_month=month_start,updated_at=now() where id=r.id;generated:=generated+1;end loop;return generated;end$$;
commit;
